<?php

declare(strict_types=1);

namespace Opencart\Catalog\Model\Api\Product;

use Exception;
use Opencart\Config\ImageConstants;
use Opencart\Config\LanguageConstants;
use Opencart\System\Engine\BaseService;
use RuntimeException;
use Throwable;

class Import extends BaseService
{
	/**
	 * @param array $payload
	 *
	 * @return array{product_id: int, action: 'created'|'updated'}
	 * @throws Exception
	 */
	public function upsertProductFromPayload(array $payload): array
	{
		$product = $payload['product'] ?? null;

		if (!is_array($product)) {
			throw new RuntimeException('Product payload is missing');
		}

		$db_prefix = (string)env('DB_PREFIX');
		$model     = $this->normalizeText((string)($product['model'] ?? ''));
		$sku       = $this->normalizeText((string)($product['sku'] ?? ''));
		$ean       = $this->normalizeText((string)($product['ean'] ?? ''));

		if ($model === '' && $ean === '') {
			throw new RuntimeException('A model or EAN is required to identify an imported product');
		}

		$this->validateProductFieldLength('model', $model, 64);
		$this->validateProductFieldLength('sku', $sku, 64);
		$this->validateProductFieldLength('ean', $ean, 14);

		$lock_names = $this->acquireProductImportLocks($model, $ean);

		try {
			if (!$this->db->beginTransaction()) {
				throw new RuntimeException('Could not start product import transaction');
			}

			try {
				$language_map = $this->resolveLanguageMap($db_prefix);
				$product_id  = $this->resolveExistingProductId($db_prefix, $model, $ean);
				$action      = $product_id > 0 ? 'updated' : 'created';
				$product_id  = $product_id > 0
					? $this->updateProduct($db_prefix, $product_id, $payload, $product, $model, $sku, $ean)
					: $this->createProduct($db_prefix, $payload, $product, $model, $sku, $ean);

				$this->ensureProductStoreAndLayout($db_prefix, $product_id);
				$this->deleteProductRelations($db_prefix, $product_id);
				$this->insertDescriptions($db_prefix, $product_id, $payload, $language_map, $model);
				$this->insertProductImages($db_prefix, $product_id, $payload, $this->makeProductImagePath((string)($product['image'] ?? '')));
				$this->insertProductCategories($db_prefix, $product_id, $payload, $language_map);
				$this->insertProductAttributes($db_prefix, $product_id, $payload, $language_map);
				$this->insertSeoUrls($db_prefix, $product_id, $payload, $language_map);
				$this->insertProductSpecials($db_prefix, $product_id, $payload);
				$this->insertProductDiscounts($db_prefix, $product_id, $payload);

				if (!$this->db->commit()) {
					throw new RuntimeException('Could not commit product import transaction');
				}

				return [
					'product_id' => $product_id,
					'action'     => $action,
				];
			} catch (Throwable $exception) {
				if ($this->db->inTransaction()) {
					$this->db->rollBack();
				}

				throw $exception;
			}
		} finally {
			$this->releaseProductImportLocks($lock_names);
		}
	}

	/** @return list<string> */
	private function acquireProductImportLocks(string $model, string $ean): array
	{
		$identifiers = [];
		if ($model !== '') {
			$identifiers[] = 'model:' . $model;
		}
		if ($ean !== '') {
			$identifiers[] = 'ean:' . $ean;
		}

		$lock_names = array_map(
			static fn (string $identifier): string => 'product-import:' . substr(hash('sha256', $identifier), 0, 48),
			$identifiers
		);
		sort($lock_names, SORT_STRING);
		$acquired_lock_names = [];

		try {
			foreach ($lock_names as $lock_name) {
				$query = $this->db->safeQuery('SELECT GET_LOCK(?, 10) AS acquired', $lock_name);
				if ((int)($query->getRow('acquired') ?? 0) !== 1) {
					throw new RuntimeException('Timed out waiting for product import lock');
				}

				$acquired_lock_names[] = $lock_name;
			}

			return $acquired_lock_names;
		} catch (Throwable $exception) {
			$this->releaseProductImportLocks($acquired_lock_names);
			throw $exception;
		}
	}

	/** @param list<string> $lock_names */
	private function releaseProductImportLocks(array $lock_names): void
	{
		foreach (array_reverse($lock_names) as $lock_name) {
			$this->db->safeQuery('SELECT RELEASE_LOCK(?) AS released', $lock_name);
		}
	}

	private function resolveExistingProductId(string $db_prefix, string $model, string $ean): int
	{
		$conditions   = [];
		$bind_params = [];
		if ($model !== '') {
			$conditions[] = '`model` = ?';
			$bind_params[] = $model;
		}
		if ($ean !== '') {
			$conditions[] = '`ean` = ?';
			$bind_params[] = $ean;
		}

		$query = $this->db->safeQuery(
			' SELECT `product_id`, `model`, `ean` FROM ' . $db_prefix . 'product WHERE ' . implode(' OR ', $conditions) . ' FOR UPDATE',
			$bind_params
		);
		$model_ids = [];
		$ean_ids   = [];
		foreach ($query->getRows() as $row) {
			$product_id = (int)($row['product_id'] ?? 0);
			if ($product_id <= 0) {
				continue;
			}
			if ($model !== '' && (string)($row['model'] ?? '') === $model) {
				$model_ids[] = $product_id;
			}
			if ($ean !== '' && (string)($row['ean'] ?? '') === $ean) {
				$ean_ids[] = $product_id;
			}
		}

		$model_ids = array_values(array_unique($model_ids));
		$ean_ids   = array_values(array_unique($ean_ids));
		if ($model !== '' && $ean !== '') {
			$matching_ids = array_values(array_intersect($model_ids, $ean_ids));
			if (count($matching_ids) === 1) {
				return $matching_ids[0];
			}
			if (count($matching_ids) > 1) {
				throw new RuntimeException('Product model and EAN match multiple OpenCart products');
			}
			if ($model_ids === [] && count($ean_ids) === 1) {
				return $ean_ids[0];
			}
			if ($ean_ids === [] && count($model_ids) === 1) {
				return $model_ids[0];
			}
			if ($model_ids !== [] && $ean_ids !== []) {
				throw new RuntimeException('Product model and EAN identify different or ambiguous OpenCart products');
			}
			if (count($model_ids) > 1 || count($ean_ids) > 1) {
				throw new RuntimeException('Product identifiers match multiple OpenCart products');
			}

			return 0;
		}

		$matching_ids = $model !== '' ? $model_ids : $ean_ids;
		if (count($matching_ids) > 1) {
			throw new RuntimeException('Product identifier matches multiple OpenCart products');
		}

		return $matching_ids[0] ?? 0;
	}

	private function createProduct(string $db_prefix, array $payload, array $product, string $model, string $sku, string $ean): int
	{
		$product_values = $this->resolveProductValues($db_prefix, $payload, $product, $model, $sku, $ean);
		$this->db->safeQuery(
			'INSERT INTO ' . $db_prefix . 'product (`model`, `sku`, `ean`, `quantity`, `image`, `manufacturer_id`, `price`, `date_available`, `minimum`, `status`, `date_added`, `date_modified`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
			$product_values
		);

		$product_id = (int)$this->db->getLastId();
		if ($product_id <= 0) {
			throw new RuntimeException('Failed to create product and resolve product_id');
		}

		return $product_id;
	}

	private function updateProduct(string $db_prefix, int $product_id, array $payload, array $product, string $model, string $sku, string $ean): int
	{
		$product_values   = $this->resolveProductValues($db_prefix, $payload, $product, $model, $sku, $ean);
		$product_values[] = $product_id;
		$this->db->safeQuery(
			'UPDATE ' . $db_prefix . 'product SET `model` = ?, `sku` = ?, `ean` = ?, `quantity` = ?, `image` = ?, `manufacturer_id` = ?, `price` = ?, `date_available` = ?, `minimum` = ?, `status` = ?, `date_added` = ?, `date_modified` = ? WHERE `product_id` = ?',
			$product_values
		);

		return $product_id;
	}

	/** @return list<int|float|string> */
	private function resolveProductValues(string $db_prefix, array $payload, array $product, string $model, string $sku, string $ean): array
	{
		$manufacturer_brand = is_array($payload['manufacturer_brand'] ?? null) ? $payload['manufacturer_brand'] : [];
		$manufacturer_id = $this->resolveManufacturerId($db_prefix, $manufacturer_brand);
		$image = $this->makeProductImagePath((string)($product['image'] ?? ''));
		$this->validateProductFieldLength('image', $image, 255);

		return [
			$model,
			$sku,
			$ean,
			max(0, (int)($product['quantity'] ?? 0)),
			$image,
			$manufacturer_id,
			(float)($product['price'] ?? 0),
			$this->normalizeDate((string)($product['date_available'] ?? '')),
			max(1, (int)($product['minimum'] ?? 1)),
			$this->normalizeBoolean($product['is_active'] ?? false) ? 1 : 0,
			$this->normalizeDateTime((string)($product['date_added'] ?? '')),
			$this->normalizeDateTime((string)($product['date_modified'] ?? '')),
		];
	}

	private function resolveManufacturerId(string $db_prefix, array $manufacturer_brand): int
	{
		$external_manufacturer_id = (int)($manufacturer_brand['external_manufacturer_id'] ?? 0);
		if ($external_manufacturer_id > 0) {
			$query = $this->db->safeQuery(
				' SELECT `manufacturer_id` FROM ' . $db_prefix . 'manufacturer WHERE `manufacturer_id` = ?',
				$external_manufacturer_id
			);
			if ((int)($query->getRow('manufacturer_id') ?? 0) > 0) {
				return $external_manufacturer_id;
			}
		}

		$manufacturer_name = oc_strtolower($this->normalizeText((string)($manufacturer_brand['manufacturer'] ?? '')));
		if ($manufacturer_name === '') {
			return 0;
		}

		$query = $this->db->safeQuery(
			' SELECT `manufacturer_id` FROM ' . $db_prefix . 'manufacturer WHERE LCASE(`name`) = ? ORDER BY `manufacturer_id` LIMIT 2',
			$manufacturer_name
		);
		$manufacturer_ids = array_map(static fn (array $row): int => (int)$row['manufacturer_id'], $query->getRows());
		if (count($manufacturer_ids) > 1) {
			throw new RuntimeException('Manufacturer name matches multiple OpenCart manufacturers');
		}

		return $manufacturer_ids[0] ?? 0;
	}

	private function validateProductFieldLength(string $field_name, string $value, int $max_length): void
	{
		if (mb_strlen($value, 'UTF-8') > $max_length) {
			throw new RuntimeException('Product ' . $field_name . ' exceeds the OpenCart limit of ' . $max_length . ' characters');
		}
	}

	private function normalizeBoolean(mixed $value): bool
	{
		return filter_var($value, FILTER_VALIDATE_BOOLEAN);
	}

	private function ensureProductStoreAndLayout(string $db_prefix, int $product_id): void
	{
		$store_id = (int)$this->config->getStoreId();
		$store_query = $this->db->safeQuery(
			' SELECT `product_id` FROM ' . $db_prefix . 'product_to_store WHERE `product_id` = ? AND `store_id` = ?',
			[$product_id, $store_id]
		);
		if ($store_query->getNumRows() === 0) {
			$this->db->safeQuery(
				'INSERT INTO ' . $db_prefix . 'product_to_store (`product_id`, `store_id`) VALUES (?, ?)',
				[$product_id, $store_id]
			);
		}

		$layout_query = $this->db->safeQuery(
			' SELECT `product_id` FROM ' . $db_prefix . 'product_to_layout WHERE `product_id` = ? AND `store_id` = ?',
			[$product_id, $store_id]
		);
		if ($layout_query->getNumRows() === 0) {
			$this->db->safeQuery(
				'INSERT INTO ' . $db_prefix . 'product_to_layout (`product_id`, `store_id`) VALUES (?, ?)',
				[$product_id, $store_id]
			);
		}
	}

	private function deleteProductRelations(string $db_prefix, int $product_id): void
	{
