			$product_id = (int)($row['product_id'] ?? 0);
			if ($product_id <= 0) {
				continue;
			}
			if ($model !== '' && (string)($row['model'] ?? '') === $model) {
				$model_ids[] = $product_id;
			}
			if ($ean !== '' && (string)($row['ean'] ?? '') === $ean) {
				$ean_ids[] = $product_id;
			}
		}

		$model_ids = array_values(array_unique($model_ids));
		$ean_ids   = array_values(array_unique($ean_ids));
		if ($model !== '' && $ean !== '') {
			$matching_ids = array_values(array_intersect($model_ids, $ean_ids));
			if (count($matching_ids) === 1) {
				return $matching_ids[0];
