		$product_values = $this->resolveProductValues($db_prefix, $payload, $product, $model, $sku, $ean);
		$this->db->safeQuery(
			'INSERT INTO ' . $db_prefix . 'product (`model`, `sku`, `ean`, `quantity`, `image`, `manufacturer_id`, `price`, `date_available`, `minimum`, `status`, `date_added`, `date_modified`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
