	function write_custom_log(string $destination_dir, string $log_name, mixed $data, bool $is_append = true): void
	{
		if (!trim(Dir::basename($log_name))) {
			return;
		}

		$log_name = date('Y_m_d') . '_' . Dir::basename($log_name);

		if (!preg_match('/\.log$/i', $log_name)) {
			$log_name .= '.log';
		}

		if ($destination_dir) {
			$destination_log_dir = Dir::logs() . date('Y/m') . '/' . trim($destination_dir, '/') . '/' . $log_name;
		} else {
			$destination_log_dir = Dir::logs() . date('Y/m') . '/' . $log_name;
		}

		if (!Dir::fileExists(Dir::dirname($destination_log_dir))) {
			Dir::makeStorageDir(Dir::dirname($destination_log_dir));
		}

		if (is_array($data) || is_object($data)) {
			$data = print_r($data, true);
		} else if (is_null($data)) {
			$data = "Data is NULL!!!\n";
		} else {
			$data = "$data\n";
		}

		if ($is_append) {
			file_put_contents($destination_log_dir, $data, FILE_APPEND);
		} else {
			file_put_contents($destination_log_dir, $data);
		}
	}
}

