	 * @param string|array $trace
	 * @param string       $error_type this is type of error and name of method for write log message
	 * @param bool         $is_send_to_telegram
	 *
	 * @return  void
	 */
	public function write(
		string       $message,
		string|array $trace = '',
		string       $error_type = 'error',
		bool         $is_send_to_telegram = true,
	): void {
		try {
			$error_type = $this->normalizeErrorType($error_type);

			if (is_array($trace)) {
				$trace      = json_encode($trace, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
				$json_error = json_last_error_msg();

				if (!empty($json_error)) {
					$trace = $json_error;
				}
			}

			$this->processWriteToFile($message, $trace, $error_type);

			// The app can send a lot of warnings and errors about absent cache files,
			// so we don't send this message to Telegram
			if ($is_send_to_telegram) {
				$this->trySendToTelegramBot($message, $error_type);
			}
		} catch (Throwable $e) {
			try {
				write_custom_log('error', 'error-log.log', [
					'message'         => $e->getMessage(),
					'trace_as_string' => $e->getTraceAsString(),
					'trace'           => $e->getTrace(),
				]);
			} catch (Throwable) {
				//
			}
		}
	}

