	{
		$this->logger_for_file->pushProcessor($this->uid_processor);
		$this->logger_for_bot->pushProcessor($this->uid_processor);

		$this->logger_for_file->pushProcessor($this->web_processor);
		$this->logger_for_bot->pushProcessor($this->web_processor);

		$this->logger_for_file->pushProcessor($this->memory_peak_usage_processor);
		$this->logger_for_bot->pushProcessor($this->memory_peak_usage_processor);

		$this->logger_for_file->pushProcessor($this->memory_usage_processor);
		$this->logger_for_bot->pushProcessor($this->memory_usage_processor);
	}

