{"label":"OpenCart logger source","exit_code":0,"output":"<?php

declare(strict_types=1);

namespace Opencart\System\Library\Trait;

use Exception;
use Opencart\System\Engine\Config;
use Opencart\System\Library\DebugBar;
use Opencart\System\Library\Log;
use Opencart\System\Library\Response;
use Opencart\System\Library\Url\UrlService;
use Throwable;

trait ControllerStartupErrorTrait
{
	public function __construct(
		private readonly Log      $log,
		private readonly Config   $config,
		private readonly Response $response,
	) {}

	/**
	 * @return void
	 */
	public function index(): void
	{
		set_error_handler([$this, 'error']);
		set_exception_handler([$this, 'exception']);
	}

	/**
	 * @param string|int $code
	 * @param string     $message
	 * @param string     $file
	 * @param string|int $line
	 *
	 * @return bool
	 * @throws Exception
	 */
	public function error(string|int $code, string $message, string $file, string|int $line): bool
	{
		$error = check_system_error($code);
		$type  = check_error_type($error);
		$trace = log_stack_trace();

		if (is_enable_debug_bar()) {
			try {
				app(DebugBar::class)->addWarning((int)$code, $message, $file, (int)$line);
			} catch (Throwable) {
				// DebugBar must never break shutdown error handling.
			}
		}

		if (ignore_error_by_message($message, $file)) {
			$this->log->write(
				message            : 'PHP ' . $error . ':  ' . $message . ' in ' . $file . ' on line ' . $line,
				trace              : $trace,
				error_type         : $type,
				is_send_to_telegram: false,
			);
		} else if ($this->config->get('config_error_log')) {
			/*$user_data = posix_getpwuid(posix_geteuid());

			$message .= PHP_EOL . print_r($user_data, true);*/

			$this->log->write(
				message   : 'PHP ' . $error . ':  ' . $message . ' in ' . $file . ' on line ' . $line,
				trace     : $trace,
				error_type: $type
			);
		}

		if (is_call_from_cli()) {
			write_message_in_terminal(
				'Something wrong in CLI operation!', true
			);

			exit($code);
		}

		if ($this->config->isErrorDisplay()) {
			if (headers_sent() === false) {
				echo '<b>' . $error . '</b>: ' . $message . ' in <b>' . $file . '</b> on line <b>' . $line . '</b>';
			}
		} else {
			$current_url = app(UrlService::class)->getPreviousUrl();

			$this->response->redirect($this->config->getErrorPage($current_url));
		}

		return true;
	}

	/**
	 * @param Throwable $e
	 *
	 * @return void
	 * @throws Exception
	 */
	public function exception(Throwable $e): void
	{
		if (is_enable_debug_bar()) {
			try {
				app(DebugBar::class)->addException($e);
			} catch (Throwable) {
				// DebugBar must never break the primary exception handler.
			}
		}

		if ($this->config->get('config_error_log')) {
			if (ignore_error_by_message($e->getMessage())) {
				$this->log->write(
					message            : $e->getMessage(),
					trace              : $e->getTraceAsString(),
					is_send_to_telegram: false,
				);
			} else {
				$this->log->write(
					message: $e->getMessage(),
					trace  : $e->getTraceAsString(),
				);
			}
		}

		if (is_call_from_cli()) {
			write_message_in_terminal(
				"Something wrong in CLI operation! \n" . $e->getTraceAsString(), true
			);

			exit($e->getCode());
		}

		if (!$this->config->isErrorDisplay()) {
			if (headers_sent() === false) {
				echo '<b>' . $e->getMessage() . '</b>: in <b>' . $e->getFile() . '</b> on line <b>' . $e->getLine() . '</b>' . PHP_EOL . $e->getTraceAsString();
			}
		} else {
			$current_url = app(UrlService::class)->getPreviousUrl();

			$this->response->redirect($this->config->getErrorPage($current_url));
		}
	}
}"}

