error_log  /var/log/nginx/error.log warn;

pid /tmp/nginx.pid;

events {
    worker_connections  1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;

    log_format  main  '$remote_addr - $remote_user [$time_local] "$request" '
                      '$status $body_bytes_sent "$http_referer" '
                      '"$http_user_agent" "$http_x_forwarded_for"';

    access_log  /var/log/nginx/access.log main;

    sendfile        on;

    keepalive_timeout  65;

    # Enable gzip
    gzip on;

    # Compression includes responses even if they are smaller than the specified size (in bytes)
    gzip_min_length 256;

    # Specify file types to compress
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript font/woff;

    # We do not compress answers for old versions IE
    gzip_disable "msie6";

    # Optimal compression settings
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;

    # Trust only Traefik IP/subnets (docker network)
    set_real_ip_from 172.18.0.0/16;   # Your docker/traefik
    real_ip_header X-Forwarded-For; # Traefik sets this header with the original client IP
    real_ip_recursive on; # Trust the X-Forwarded-For header from Traefik, which may contain multiple IPs. The last one is the original client.

    server {
        listen       80;
        index                     index.php index.html index.htm index.phtml;
        server_name  localhost;
        root /var/webroot/sites/phnw8.strateg.ua/httpdocs;

        # This feature is needed to download very large files
        # Internal location: /{market}/feed-file/{filename} -> /var/webroot/sites/phnw8.strateg.ua/storage/feeds/{market}/{filename}
        # Important: {filename} must be basename only (no slashes).
        location ~ ^/(?<market>[a-z0-9_-]+)/feed-file/(?<filename>[^/]+)$ {
            internal; # <-- This location is NOT accessible directly from browser

            # Use root + captured market + filename (no slashes in filename).
            # This prevents directory traversal.
            root /var/webroot/sites/phnw8.strateg.ua/storage/feed;
            try_files /$market/$filename =404;

            types {
                application/xml xml;
            }

            add_header Cache-Control "no-cache, must-revalidate";
            add_header Pragma "no-cache";
        }

        location / {
            try_files $uri $uri/ @rewrite;
        }

        location @rewrite {
            rewrite ^\/(.*)$ /index.php?_route_=$1 last;
        }

        location /landing/keramicheskij-konstruktor/index.html {
            return 301 http://$host/landing/keramichni-blocky/frontend/index.phtml;
        }

        location = /xhprof {
            return 301 /xhprof/xhprof_html/;
        }

        location ^~ /xhprof/ {
            root /var/webroot/sites/phnw8.strateg.ua;
            index index.php;
            try_files $uri $uri/ /xhprof/xhprof_html/index.php?$query_string;

            location ~ \.php$ {
                fastcgi_pass dev-strateg-php-fpm:9000;
                fastcgi_param SCRIPT_FILENAME $realpath_root$fastcgi_script_name;

                # Pass real client IP to PHP ($_SERVER['HTTP_X_REAL_IP'])
                fastcgi_param HTTP_X_REAL_IP       $remote_addr;
                fastcgi_param HTTP_X_FORWARDED_FOR $remote_addr;

                # Reuse the same FastCGI timeouts as the main PHP entrypoint.
                fastcgi_connect_timeout 120;
                fastcgi_send_timeout    120;
                fastcgi_read_timeout    180;

                include fastcgi_params;
            }
        }

        location ^~ /vendor/php-debugbar/php-debugbar/resources/ {
            expires max;
            log_not_found off;
        }

        location ^~ /vendor/ {
            deny all;
        }

        location ~ \.(gif|bmp|css|zip|tgz|gz|rar|bz2|doc|xls|exe|pdf|ppt|txt|tar|mid|midi|wav|rtf|js)$ {
            expires max;
            log_not_found off;
        }

        location ~* \.(tpl|twig|ini|log|txt)$ {
            deny all;
        }

        location ~ \.(php|phtml)$ {
            fastcgi_pass dev-strateg-php-fpm:9000;
            fastcgi_param SCRIPT_FILENAME $realpath_root$fastcgi_script_name;

            # Pass real client IP to PHP ($_SERVER['HTTP_X_REAL_IP'])
            fastcgi_param HTTP_X_REAL_IP      $remote_addr;
            fastcgi_param HTTP_X_FORWARDED_FOR $remote_addr;

            # FastCGI timeouts
            fastcgi_connect_timeout 120;
            fastcgi_send_timeout    120;
            fastcgi_read_timeout    180;

            include fastcgi_params;
        }

        location ~ /\.ht {
            deny  all;
        }

        add_header Referrer-Policy "no-referrer" always;
        add_header X-Content-Type-Options "nosniff" always;
        add_header Permissions-Policy "interest-cohort=()" always;

        client_max_body_size 100M;
        fastcgi_buffer_size 256k;
        fastcgi_buffers 64 16k;
        fastcgi_busy_buffers_size 256k;
    }

    include /etc/nginx/conf.d/*.conf;
}

