        ->unique()
        ->values()
        ->all();

    $persisted_language_ids = collect($normalized_language_ids)
        ->filter(static fn (int $shop_language_id): bool => $shop_language_id > 0)
        ->values()
        ->all();

    if ($persisted_language_ids !== []) {
