declare(strict_types=1);

namespace Opencart\Catalog\Model\Api\Product;

use Exception;
use Opencart\Config\ImageConstants;
use Opencart\Config\LanguageConstants;
use Opencart\System\Engine\BaseService;
use RuntimeException;
use Throwable;

class Import extends BaseService
{
	/**
	 * @param array $payload
	 *
	 * @return array{product_id: int, action: 'created'|'updated'}
	 * @throws Exception
	 */
	public function upsertProductFromPayload(array $payload): array
	{
		$product = $payload['product'] ?? null;

		if (!is_array($product)) {
			throw new RuntimeException('Product payload is missing');
		}

		$db_prefix = (string)env('DB_PREFIX');
		$model     = $this->normalizeText((string)($product['model'] ?? ''));
		$sku       = $this->normalizeText((string)($product['sku'] ?? ''));
		$ean       = $this->normalizeText((string)($product['ean'] ?? ''));

		if ($model === '' && $ean === '') {
			throw new RuntimeException('A model or EAN is required to identify an imported product');
		}

		$this->validateProductFieldLength('model', $model, 64);
		$this->validateProductFieldLength('sku', $sku, 64);
		$this->validateProductFieldLength('ean', $ean, 14);

		$lock_names = $this->acquireProductImportLocks($model, $ean);

		try {
			if (!$this->db->beginTransaction()) {
				throw new RuntimeException('Could not start product import transaction');
			}

			try {
				$language_map = $this->resolveLanguageMap($db_prefix);
				$product_id  = $this->resolveExistingProductId($db_prefix, $model, $ean);
				$action      = $product_id > 0 ? 'updated' : 'created';
				$product_id  = $product_id > 0
					? $this->updateProduct($db_prefix, $product_id, $payload, $product, $model, $sku, $ean)
					: $this->createProduct($db_prefix, $payload, $product, $model, $sku, $ean);

				$this->ensureProductStoreAndLayout($db_prefix, $product_id);
				$this->deleteProductRelations($db_prefix, $product_id);
				$this->insertDescriptions($db_prefix, $product_id, $payload, $language_map, $model);
				$this->insertProductImages($db_prefix, $product_id, $payload, $this->makeProductImagePath((string)($product['image'] ?? '')));
				$this->insertProductCategories($db_prefix, $product_id, $payload, $language_map);
				$this->insertProductAttributes($db_prefix, $product_id, $payload, $language_map);
				$this->insertSeoUrls($db_prefix, $product_id, $payload, $language_map);
				$this->insertProductSpecials($db_prefix, $product_id, $payload);
				$this->insertProductDiscounts($db_prefix, $product_id, $payload);

				if (!$this->db->commit()) {
					throw new RuntimeException('Could not commit product import transaction');
				}

				return [
					'product_id' => $product_id,
					'action'     => $action,
				];
			} catch (Throwable $exception) {
				if ($this->db->inTransaction()) {
					$this->db->rollBack();
				}

				throw $exception;
			}
		} finally {
			$this->releaseProductImportLocks($lock_names);
		}
	}

	/** @return list<string> */
	private function acquireProductImportLocks(string $model, string $ean): array
	{
		$identifiers = [];
		if ($model !== '') {
			$identifiers[] = 'model:' . $model;
		}
		if ($ean !== '') {
			$identifiers[] = 'ean:' . $ean;
		}

		$lock_names = array_map(
			static fn (string $identifier): string => 'product-import:' . substr(hash('sha256', $identifier), 0, 48),
			$identifiers
		);
		sort($lock_names, SORT_STRING);
		$acquired_lock_names = [];

		try {
			foreach ($lock_names as $lock_name) {
				$query = $this->db->safeQuery('SELECT GET_LOCK(?, 10) AS acquired', $lock_name);
				if ((int)($query->getRow('acquired') ?? 0) !== 1) {
					throw new RuntimeException('Timed out waiting for product import lock');
				}

				$acquired_lock_names[] = $lock_name;
			}

			return $acquired_lock_names;
		} catch (Throwable $exception) {
			$this->releaseProductImportLocks($acquired_lock_names);
			throw $exception;
		}
	}

	/** @param list<string> $lock_names */
	private function releaseProductImportLocks(array $lock_names): void
	{
		foreach (array_reverse($lock_names) as $lock_name) {
			$this->db->safeQuery('SELECT RELEASE_LOCK(?) AS released', $lock_name);
		}
	}

	private function resolveExistingProductId(string $db_prefix, string $model, string $ean): int
	{
		$conditions   = [];
		$bind_params = [];
		if ($model !== '') {
			$conditions[] = '`model` = ?';
			$bind_params[] = $model;
		}
		if ($ean !== '') {
			$conditions[] = '`ean` = ?';
			$bind_params[] = $ean;
		}

		$query = $this->db->safeQuery(
			' SELECT `product_id`, `model`, `ean` FROM ' . $db_prefix . 'product WHERE ' . implode(' OR ', $conditions) . ' FOR UPDATE',
			$bind_params
		);
		$model_ids = [];
		$ean_ids   = [];
		foreach ($query->getRows() as $row) {
			$product_id = (int)($row['product_id'] ?? 0);
			if ($product_id <= 0) {
				continue;
			}
			if ($model !== '' && (string)($row['model'] ?? '') === $model) {
				$model_ids[] = $product_id;
			}
			if ($ean !== '' && (string)($row['ean'] ?? '') === $ean) {
				$ean_ids[] = $product_id;
			}
		}

		$model_ids = array_values(array_unique($model_ids));
