	/** @return list<string> */
	private function acquireProductImportLocks(string $model, string $ean): array
	{
		$identifiers = [];
		if ($model !== '') {
			$identifiers[] = 'model:' . $model;
		}
		if ($ean !== '') {
			$identifiers[] = 'ean:' . $ean;
		}

		$lock_names = array_map(
			static fn (string $identifier): string => 'product-import:' . substr(hash('sha256', $identifier), 0, 48),
			$identifiers
		);
		sort($lock_names, SORT_STRING);
		$acquired_lock_names = [];

		try {
			foreach ($lock_names as $lock_name) {
				$query = $this->db->safeQuery('SELECT GET_LOCK(?, 10) AS acquired', $lock_name);
				if ((int)($query->getRow('acquired') ?? 0) !== 1) {
					throw new RuntimeException('Timed out waiting for product import lock');
				}

				$acquired_lock_names[] = $lock_name;
			}

			return $acquired_lock_names;
		} catch (Throwable $exception) {
			$this->releaseProductImportLocks($acquired_lock_names);
			throw $exception;
		}
	}

	/** @param list<string> $lock_names */
	private function releaseProductImportLocks(array $lock_names): void
	{
		foreach (array_reverse($lock_names) as $lock_name) {
			$this->db->safeQuery('SELECT RELEASE_LOCK(?) AS released', $lock_name);
		}
	}

